// app/Sources/ProjectDocument+GraphicInsert.swift — the two halves of
// Insert ▸ Graphic… that both doors share (spec §11 G-16, G-45 (f)): the
// sheet's Insert and From File… (`EditorViewController+GraphicMenus.swift`)
// and `insert_graphic` (`AgentServer+GraphicBrowser.swift`).
//
// `writeGraphicModule` is G-16 (b): a module's text copied into the
// package's `graphics/` under a free name, then the folder rescanned so the
// registry has compiled THAT text. `rescan()` runs here, from a command,
// never from a `.graphicsDidChange` observer (`drain()` is not re-entrant).
// The file write is not undoable (G-3).
//
// `graphicClipMaker` is the clip: `add_graphic_clip` at the module's `meta`
// duration and size, with the schema of its current revision (G-4). Where
// the clip goes is each caller's: `EditorViewController.generatedClipOps`,
// Add Text's rule (G-16 (a)). A module that does not compile places nothing
// and throws its first diagnostic (G-45 (f)).

import Foundation

extension ProjectDocument {
    /// The sentence for a document whose graphics store has not started —
    /// one with no window.
    static let noGraphicsFolderSentence =
        "This project has no graphics folder open (its window has not been made)"

    /// Writes `url`'s module into `graphics/` under a free name made from
    /// its stem (G-16 (b)) and rescans; the name it was written under.
    /// Throws, writing nothing, when the file cannot be read or is not
    /// UTF-8.
    func writeGraphicModule(from url: URL) throws -> String {
        guard let store = graphicStore else {
            throw ReelCoreError(message: Self.noGraphicsFolderSentence)
        }
        let bytes: Data
        do {
            bytes = try Data(contentsOf: url)
        } catch {
            throw ReelCoreError(
                message: "\(url.path) could not be read: \(error.localizedDescription)")
        }
        guard let source = String(data: bytes, encoding: .utf8) else {
            throw ReelCoreError(
                message: "\(url.path) is not UTF-8 text — a graphic module must be UTF-8 "
                    + "JavaScript")
        }
        let name = store.uniqueModuleName(
            GraphicTemplates.moduleName(from: url.deletingPathExtension().lastPathComponent))
        try store.write(name: name, source: source)
        store.rescan()
        return name
    }

    /// The op that places one clip drawn by `graphics/<name>.js` at a track
    /// and a time: its `meta` duration and size, its schema. Throws the
    /// module's first diagnostic when it does not compile, the store's
    /// sentence when the folder does not hold it, and the `meta` sentence
    /// when a duration or side is not a whole number in range.
    func graphicClipMaker(named name: String) throws -> (UInt32, Ticks) -> ReelOp {
        guard let store = graphicStore else {
            throw ReelCoreError(message: Self.noGraphicsFolderSentence)
        }
        guard let entry = GraphicRegistry.shared.entry(named: name, for: recipeKey) else {
            throw ReelCoreError(message: store.noModuleSentence(name))
        }
        guard case .compiled(_, _, let meta, let schema) = entry else {
            var first: GraphicDiagnostic?
            if case .failed(let diagnostics, _) = entry { first = diagnostics.first }
            let line = first?.line.map { " (line \($0))" } ?? ""
            throw ReelCoreError(
                message: "graphics/\(name).js does not compile: "
                    + (first?.message ?? "no diagnostic") + line)
        }
        let frame = max(project.snapshot.canvas.fps.frameDuration, 1)
        let duration: Ticks?
        let width: UInt32?
        let height: UInt32?
        do {
            duration = try AgentServer.metaWhole(
                meta, "durationInFrames", name, in: 1...Int.max / Int(frame)
            ).map { Ticks($0) * frame }
            width = try AgentServer.metaWhole(meta, "width", name, in: AgentServer.sides)
                .map(UInt32.init)
            height = try AgentServer.metaWhole(meta, "height", name, in: AgentServer.sides)
                .map(UInt32.init)
        } catch let error as AgentServer.ToolError {
            throw ReelCoreError(message: error.message)
        }
        return { track, at in
            .addGraphicClipRaw(
                track: track, at: at, duration: duration, name: name, width: width,
                height: height, props: nil, schema: schema)
        }
    }
}

1	// app/Sources/GraphicCatalog.swift — what Insert ▸ Graphic… lists (spec §11
2	// G-45): the bundled templates and the project's own modules as categories
3	// of graphics, in the one order the sheet (`GraphicBrowserSheetController`)
4	// and `list_graphics` (`AgentServer+GraphicBrowser.swift`) both show.
5	//
6	// **A template is compiled to read its `meta`, once per process**
7	// (`GraphicTemplateLibrary`, G-45 (e)): its title is `meta.name`, its
8	// category `meta.category`, its description `meta.description`. The first
9	// read is on main, when the browser or the tool first asks; it compiles
10	// against a library of the bundled fonts alone and is memoised under a lock.
11	// The menu bar never reads it (chrome probes instantiate `AppDelegate()`).
12	//
13	// **A project module is read from the registry**: the document's compiled
14	// set, as the inspector and the op tools read it. A module that does not
15	// compile is still listed (`ok` false), titled from its stem, so a person
16	// can see it is there and read why it will not insert.
17	
18	import Foundation
19	
20	/// One graphic the browser lists.
21	struct GraphicBrowserItem: Equatable {
22	    enum Origin: String { case template, project }
23	    /// A template's file stem; a project module's name.
24	    let name: String
25	    /// `GraphicCatalog.title(meta:name:)`; a This Project duplicate carries
26	    /// " — <name>" (G-45 (e)).
27	    let title: String
28	    let description: String?
29	    /// The module's own category (`meta.category`, else "Other") — a This
30	    /// Project item keeps its own here though it is listed under This Project.
31	    let category: String
32	    let origin: Origin
33	    /// The module compiled.
34	    let ok: Bool
35	}
36	
37	/// One category and its graphics, in order.
38	struct GraphicBrowserCategory: Equatable {
39	    let name: String
40	    let items: [GraphicBrowserItem]
41	}
42	
43	enum GraphicCatalog {
44	    static let thisProject = "This Project", other = "Other"
45	
46	    /// G-45 (a): `meta.category` trimmed when it is a non-empty string, else
47	    /// "Other".
48	    static func category(meta: [String: Any]) -> String {
49	        let named = (meta["category"] as? String)?
50	            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
51	        return named.isEmpty ? other : named
52	    }
53	
54	    /// G-45 (e): `meta.name` when it is a non-empty string, else the stem's
55	    /// title (`GraphicTemplates.title(for:)`).
56	    static func title(meta: [String: Any], name: String) -> String {
57	        let named = (meta["name"] as? String)?
58	            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
59	        return named.isEmpty ? GraphicTemplates.title(for: name) : named
60	    }
61	
62	    /// `meta.description` trimmed, nil when absent or blank.
63	    static func description(meta: [String: Any]) -> String? {
64	        let text = (meta["description"] as? String)?
65	            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
66	        return text.isEmpty ? nil : text
67	    }
68	
69	    /// One item from a compiled (or failed, or absent) registry entry.
70	    static func item(
71	        name: String, entry: GraphicRegistry.Entry?, origin: GraphicBrowserItem.Origin
72	    ) -> GraphicBrowserItem {
73	        var meta: [String: Any] = [:]
74	        var ok = false
75	        if case .compiled(_, _, let described, _)? = entry {
76	            meta = described
77	            ok = true
78	        }
79	        return GraphicBrowserItem(
80	            name: name, title: title(meta: meta, name: name), description: description(meta: meta),
81	            category: category(meta: meta), origin: origin, ok: ok)
82	    }
83	
84	    /// G-45 (d): This Project first, only when `project` holds an item, with
85	    /// (e)'s duplicate titles told apart; then the templates' categories by
86	    /// case-insensitive name, Other last. Items by title case-insensitively,
87	    /// then by name.
88	    static func categories(
89	        templates: [GraphicBrowserItem], project: [GraphicBrowserItem]
90	    ) -> [GraphicBrowserCategory] {
91	        let ours: [GraphicBrowserCategory] = project.isEmpty ? []
92	            : [GraphicBrowserCategory(name: thisProject, items: sorted(distinguished(project)))]
93	        let names = Set(templates.map(\.category)).sorted { a, b in
94	            if (a == other) != (b == other) { return b == other }
95	            return a.caseInsensitiveCompare(b) == .orderedAscending
96	        }
97	        let theirs = names.map { name in
98	            GraphicBrowserCategory(
99	                name: name, items: sorted(templates.filter { $0.category == name }))
100	        }
101	        return ours + theirs
102	    }
103	
104	    /// The document's list: the bundled templates and the modules its
105	    /// `graphics/` holds as the registry compiled them. Main.
106	    static func categories(for document: ProjectDocument) -> [GraphicBrowserCategory] {
107	        let templates = GraphicTemplateLibrary.shared.entries.map {
108	            item(name: $0.template.name, entry: $0.entry, origin: .template)
109	        }
110	        let modules = document.graphicStore?.scan.modules.keys.sorted() ?? []
111	        let project = modules.map {
112	            item(
113	                name: $0, entry: GraphicRegistry.shared.entry(named: $0, for: document.recipeKey),
114	                origin: .project)
115	        }
116	        return categories(templates: templates, project: project)
117	    }
118	
119	    /// By title, case-insensitively, then by name.
120	    private static func sorted(_ items: [GraphicBrowserItem]) -> [GraphicBrowserItem] {
121	        items.sorted { a, b in
122	            switch a.title.caseInsensitiveCompare(b.title) {
123	            case .orderedAscending: return true
124	            case .orderedDescending: return false
125	            case .orderedSame: return a.name < b.name
126	            }
127	        }
128	    }
129	
130	    /// Every item whose title another item shares, case-insensitively,
131	    /// titled "<title> — <name>".
132	    private static func distinguished(_ items: [GraphicBrowserItem]) -> [GraphicBrowserItem] {
133	        var counts: [String: Int] = [:]
134	        let key = { (title: String) in title.folding(options: .caseInsensitive, locale: nil) }
135	        for item in items { counts[key(item.title), default: 0] += 1 }
136	        return items.map { item in
137	            guard counts[key(item.title), default: 0] > 1 else { return item }
138	            return GraphicBrowserItem(
139	                name: item.name, title: "\(item.title) — \(item.name)",
140	                description: item.description, category: item.category, origin: item.origin,
141	                ok: item.ok)
142	        }
143	    }
144	}
145	
146	/// The bundled templates, compiled once against a library of the bundled
147	/// fonts (G-45 (e)): what the browser reads their `meta` from and what its
148	/// preview draws them with.
149	final class GraphicTemplateLibrary {
150	    struct Entry {
151	        let template: GraphicTemplate
152	        let entry: GraphicRegistry.Entry
153	    }
154	
155	    static let shared = GraphicTemplateLibrary(
156	        directory: GraphicTemplates.bundledDirectory, fonts: ProjectDocument.bundledFontsDirectory)
157	
158	    private let directory: URL
159	    private let fonts: URL
160	    private let lock = NSLock()
161	    private var compiled: [Entry]?
162	
163	    init(directory: URL, fonts: URL) {
164	        self.directory = directory
165	        self.fonts = fonts
166	    }
167	
168	    /// Every template in `GraphicTemplates.list(in:)`'s order, compiled on
169	    /// the first read and kept. The first read is on main.
170	    var entries: [Entry] {
171	        lock.lock()
172	        defer { lock.unlock() }
173	        if let compiled = compiled { return compiled }
174	        let made = compile()
175	        compiled = made
176	        return made
177	    }
178	
179	    func entry(named name: String) -> Entry? {
180	        entries.first { $0.template.name == name }
181	    }
182	
183	    /// The bundled faces into a new library, then every template compiled
184	    /// against it. A face the engine refuses fails every template with its
185	    /// sentence, as `GraphicRegistry.install` does for a document.
186	    private func compile() -> [Entry] {
187	        let templates = GraphicTemplates.list(in: directory)
188	        let library = GraphicLibrary()
189	        var refused: [GraphicDiagnostic]?
190	        let faces = ((try? FileManager.default.contentsOfDirectory(
191	            at: fonts, includingPropertiesForKeys: nil)) ?? [])
192	            .filter { GraphicStore.fontExtensions.contains($0.pathExtension.lowercased()) }
193	            .sorted { $0.lastPathComponent < $1.lastPathComponent }
194	        do {
195	            for face in faces { try library.addFont(Data(contentsOf: face)) }
196	        } catch {
197	            refused = GraphicDiagnostic.of(error)
198	        }
199	        return templates.map { template in
200	            let bytes = (try? Data(contentsOf: template.url)) ?? Data()
201	            if let refused = refused {
202	                return Entry(template: template, entry: .failed(refused, revision: ""))
203	            }
204	            let file = GraphicModuleFile(
205	                name: template.name, url: template.url, bytes: bytes, revision: "")
206	            return Entry(template: template, entry: GraphicRegistry.compile(file, library: library))
207	        }
208	    }
209	}
