4	/// The graphics menu commands (road map 10's G5b; spec §11 G-45): Insert ▸
5	/// Graphic…, the sheet (`GraphicBrowserSheetController.swift`) and its From
6	/// File…, and File ▸ Add Font to Graphics… and Add Image to Graphics…. Each
7	/// is the same code its MCP tool runs.
8	///
9	/// **Insert is `write_graphic` then `add_graphic_clip`** (spec §7.9) for a
10	/// template or a chosen `.js`: the module is written into the package's
11	/// `graphics/` under a free name and the folder rescanned
12	/// (`ProjectDocument.writeGraphicModule`, G-16 (b)), and one clip is placed
13	/// by `addGeneratedClip`'s rule — the front track if it fits, else a new
14	/// track above everything, Add Text's rule (G-16 (a)) — at the module's
15	/// `meta` duration and size (`ProjectDocument.graphicClipMaker`). A This
16	/// Project graphic is the clip alone, no copy (G-45 (f)). A module that does
17	/// not compile places nothing (G-16 (c)); the file write is not undoable
18	/// (G-3) and the clip is one undo step, "Insert Graphic". `insert_graphic`
19	/// calls the same two document bodies.
20	///
21	/// **From File… takes a `.fjgraphic` too** (spec §11 G-47 (a)): the package
22	/// goes to `GraphicImportSheetController.ask(packageAt:editor:)`, which asks
23	/// before copying it into this project's `graphics/`; a `.js` is inserted as
24	/// before.
25	///
26	/// The sheet's Insert runs INSIDE its button's event, so `applyEdit`; the
27	/// panels' completions are OFF-EVENT, so `performGroupedEdit` (app/CLAUDE.md's
28	/// undo pitfall). `rescan()` is called from the command, never from a
29	/// `.graphicsDidChange` observer.
30	extension EditorViewController {
31	
32	    /// Insert ▸ Graphic…: the browser, as a sheet on the editor's window.
33	    @objc func showGraphicBrowser(_ sender: Any?) {
34	        guard let document = document, document.graphicStore != nil else {
35	            NSSound.beep()
36	            return
37	        }
38	        let sheet = GraphicBrowserSheetController(document: document, editor: self)
39	        presentAsSheet(sheet)
40	    }
41	
42	    /// The browser after an import (spec §11 G-47 (f)): This Project's `name` chosen and
43	    /// `message` in its message line.
44	    func showGraphicBrowser(selecting name: String, message: String) {
45	        guard let document = document, document.graphicStore != nil else {
46	            NSSound.beep()
47	            return
48	        }
49	        presentAsSheet(GraphicBrowserSheetController(
50	            document: document, editor: self, select: name, message: message))
51	    }
52	
53	    /// The sheet's From File…: a `.js` or a `.fjgraphic` chosen in a panel. Called from the
54	    /// browser's `viewDidDisappear`, once the browser is down, so the panel
55	    /// is the sheet that follows it.
56	    func insertGraphicFromFile(_ sender: Any?) {
57	        guard document?.graphicStore != nil, let window = view.window else {
58	            NSSound.beep()
59	            return
60	        }
61	        let panel = NSOpenPanel()
62	        panel.allowsMultipleSelection = false
63	        panel.canChooseDirectories = false
64	        panel.allowedContentTypes = [.javaScript, GraphicPackage.contentType]
65	        panel.message = "Choose a graphic module (.js) or a graphic package (.fjgraphic) to copy "
66	            + "into this project's graphics."
67	        panel.beginSheetModal(for: window) { [weak self] response in
68	            guard let self, response == .OK, let url = panel.url else { return }
69	            if url.pathExtension.lowercased() == GraphicPackage.fileExtension {
70	                GraphicImportSheetController.ask(packageAt: url, editor: self)
71	                return
72	            }
73	            self.reportingGraphicFailure { try self.insertGraphic(from: url, grouped: true) }
74	        }
75	    }
76	
77	    /// File ▸ Add Font to Graphics… — `import_graphic_font`'s body.
78	    @objc func addGraphicFont(_ sender: Any?) {
79	        chooseGraphicFile(
80	            types: GraphicStore.fontExtensions,
81	            message: "Choose a font (.ttf or .otf) to add to this project's graphics."
82	        ) { store, url in
83	            _ = try store.importFont(from: url)
84	        }
85	    }
86	
87	    /// File ▸ Add Image to Graphics… — `import_graphic_asset`'s body, filed
88	    /// under the picture's own name.
89	    @objc func addGraphicImage(_ sender: Any?) {
90	        chooseGraphicFile(
91	            types: GraphicStore.assetExtensions,
92	            message: "Choose a picture (\(GraphicStore.assetKinds)) to add to this project's "
93	                + "graphics."
94	        ) { [weak self] _, url in try self?.addGraphicImage(from: url) }
95	    }
96	
97	    /// Add Image's body, no panel: the picture filed under its own name, or
98	    /// under a legal one with a sheet saying so (spec §11 G-23 (d)).
99	    func addGraphicImage(from url: URL) throws {
100	        guard let document = document, let store = document.graphicStore else {
101	            throw ReelCoreError(
102	                message: "This project has no graphics folder open (its window has not been made)")
103	        }
104	        let landed = try store.importAsset(from: url, as: url.lastPathComponent)
105	        if let asked = landed.renamedFrom, view.window != nil {
106	            showGraphicNotice(GraphicAssetName.renameNotice(from: asked, to: landed.name))
107	        }
108	    }
109	
110	    /// The body, no dialog: write `url`'s module under a free name, rescan,
111	    /// and place a clip drawn by it — or throw the sentence saying why not.
112	    func insertGraphic(from url: URL, grouped: Bool) throws {
113	        guard let document = document else {
114	            throw ReelCoreError(message: ProjectDocument.noGraphicsFolderSentence)
115	        }
116	        let written = try document.writeGraphicModule(from: url)
117	        let make = try document.graphicClipMaker(named: written)
118	        addGeneratedClip(named: "Insert Graphic", grouped: grouped, make)
119	    }
120	
121	    /// A This Project graphic placed: a clip drawn by `graphics/<name>.js`
122	    /// as it is, no copy written (spec §11 G-45 (f)) — or the sentence
123	    /// saying why not.
124	    func insertProjectGraphic(named name: String, grouped: Bool) throws {
125	        guard let document = document else {
126	            throw ReelCoreError(message: ProjectDocument.noGraphicsFolderSentence)
127	        }
128	        let make = try document.graphicClipMaker(named: name)
129	        addGeneratedClip(named: "Insert Graphic", grouped: grouped, make)
130	    }
131	
132	    /// The menu arms for the three, answered from `validateUserInterfaceItem`'s
133	    /// default case: each needs the document's graphics store, which
134	    /// `startGraphicStore()` makes with the window. Any other action is
135	    /// forwarded to `validateGraphicFileAction`, the arm for File ▸ Rename
136	    /// Graphic…, Delete Graphic… and Restore Graphic Version…
137	    /// (`EditorViewController+GraphicFiles.swift`), which answers nil for
138	    /// an action that is none of the three.
139	    func validateGraphicMenuAction(_ action: Selector) -> Bool? {
140	        switch action {
141	        case #selector(showGraphicBrowser(_:)), #selector(addGraphicFont(_:)),
142	            #selector(addGraphicImage(_:)):
143	            return document?.graphicStore != nil
144	        default:
145	            return validateGraphicFileAction(action)
146	        }
147	    }
148	
149	    // MARK: - Helpers
150	
151	    /// A file panel over `types` (file extensions); its completion runs
152	    /// `body` with the store and the chosen URL, a failure in a sheet.
153	    private func chooseGraphicFile(
154	        types: Set<String>, message: String,
155	        _ body: @escaping (GraphicStore, URL) throws -> Void
156	    ) {
157	        guard let store = document?.graphicStore, let window = view.window else {
158	            NSSound.beep()
159	            return
160	        }
161	        let panel = NSOpenPanel()
162	        panel.allowsMultipleSelection = false
163	        panel.canChooseDirectories = false
164	        panel.allowedContentTypes = types.sorted().compactMap { UTType(filenameExtension: $0) }
165	        panel.message = message
166	        panel.beginSheetModal(for: window) { [weak self] response in
167	            guard response == .OK, let url = panel.url else { return }
168	            self?.reportingGraphicFailure { try body(store, url) }
169	        }
170	    }
171	
172	    /// Runs `body`; a throw is shown in a sheet on the editor's window
173	    /// (`addImageBackground`'s shape), or a beep with no window. Success
174	    /// shows nothing.
175	    private func reportingGraphicFailure(_ body: () throws -> Void) {
176	        do {
177	            try body()
178	        } catch {
179	            guard let window = view.window else {
180	                NSSound.beep()
181	                return
182	            }
183	            NSAlert(error: error).beginSheetModal(for: window, completionHandler: nil)
184	        }
185	    }
186	
187	    /// An informational sheet on the editor's window saying `text`.
188	    private func showGraphicNotice(_ text: String) {
189	        guard let window = view.window else { return }
190	        let alert = NSAlert()
191	        alert.alertStyle = .informational
192	        alert.messageText = text
193	        alert.beginSheetModal(for: window, completionHandler: nil)
194	    }
195	}
