// app/Sources/GraphicAssetName.swift — what an asset may be called, so that
// `asset(name)` can use it (spec §11 G-23). Pure: the rule, the legaliser
// both import doors run, the `-N` suffixer for a renamed copy whose legal
// name is held, and the sentences. The scan skips an illegal file by `isLegal`.

import Foundation

enum GraphicAssetName {
    /// 255 (APFS's name limit) − ".partial".utf8.count: `GraphicStore.land(at:writing:)`
    /// (GraphicStore+Files.swift) writes `<name>.partial` first.
    static let maxBytes = 247
    static let rule = "is not an asset name (no leading . or #; no / : \" ' < > & or "
        + "control character; at most \(maxBytes) bytes)"

    private static let forbidden: Set<Unicode.Scalar> = ["/", ":", "\"", "'", "<", ">", "&"]

    private static func isForbidden(_ s: Unicode.Scalar) -> Bool {
        forbidden.contains(s) || s.value <= 0x1F || (0x7F...0x9F).contains(s.value)
    }

    static func isLegal(_ name: String) -> Bool {
        let scalars = Array(name.unicodeScalars)
        guard let head = scalars.first, name.utf8.count <= maxBytes else { return false }
        return head != "." && head != "#" && !scalars.contains(where: isForbidden)
    }

    /// Precondition: `name` is non-empty, holds no "/", and its extension is one of
    /// `GraphicStore.assetExtensions`. Identity on a legal name.
    static func legalized(_ name: String) -> String {
        let (stem, ext) = split(name)
        var scalars = Array(stem)
        while let head = scalars.first, head == "." || head == "#" || isForbidden(head) {
            scalars.removeFirst()
        }
        while let tail = scalars.last, isForbidden(tail) { scalars.removeLast() }
        var clean: [Unicode.Scalar] = []
        var inRun = false
        for s in scalars {
            if !isForbidden(s) {
                clean.append(s)
            } else if !inRun {
                clean.append("-")
            }
            inRun = isForbidden(s)
        }
        if clean.isEmpty { clean = Array("image".unicodeScalars) }
        return fitted(clean, suffix: ext)
    }

    /// `<stem>-<n>.<ext>`, the stem's tail cut by whole scalars so the result is ≤ maxBytes.
    static func withSuffix(_ name: String, _ n: Int) -> String {
        let (stem, ext) = split(name)
        return fitted(stem, suffix: "-\(n)" + ext)
    }

    static func renameNotice(from: String, to: String) -> String {
        "\"\(from)\" was added as \"\(to)\": asset(name) cannot use the name it had."
    }

    /// The scalars before the last ".", and the rest from that "." on ("" when none).
    private static func split(_ name: String) -> ([Unicode.Scalar], String) {
        let scalars = Array(name.unicodeScalars)
        guard let dot = scalars.lastIndex(of: ".") else { return (scalars, "") }
        let ext = String(String.UnicodeScalarView(scalars[dot...]))
        return (Array(scalars[..<dot]), ext)
    }

    /// `stem` cut by whole scalars from its tail until `stem + suffix` fits maxBytes.
    private static func fitted(_ stem: [Unicode.Scalar], suffix: String) -> String {
        var stem = stem
        let budget = maxBytes - suffix.utf8.count
        var bytes = stem.reduce(0) { $0 + String($1).utf8.count }
        while bytes > budget, let last = stem.popLast() { bytes -= String(last).utf8.count }
        return String(String.UnicodeScalarView(stem)) + suffix
    }
}
// app/Sources/GraphicStore+Import.swift — a font or a picture copied into
// `graphics/fonts/` or `graphics/assets/` (road map 10 §5h, G4b; G5b): the
// ONE body behind the agent's `import_graphic_font` and
// `import_graphic_asset` and a person's File ▸ Add Font to Graphics… and
// Add Image to Graphics…, so the two doors refuse in the same sentences.
//
// It goes through `ensureFolder()`, the ONE creator of `graphics/` inside a
// package (G-14), and lands the file the way `write(name:source:)` lands a
// module: a `<name>.partial` beside it, then moved into place, so the scan
// never reads half a file (a `.partial`'s extension is in neither the font
// nor the asset set, so it is never listed). `importFile` does not rescan;
// `importFont` and `importAsset` end in ONE `rescan()`, so the registry has
// its new library when they return — both are called from a handler or a
// command, never from a `.graphicsDidChange` observer (`drain()` is not
// re-entrant).
//
// **A font's family names are the ENGINE's own** (`rc_graphic_library_families`):
// the file is loaded into a throwaway library of its own and that library is
// asked, so `families` is exactly what a `font-family` must say — CoreText
// names some files differently (road map 10 §10.7 G4b measured 13 of 2500).
// Not undoable and never dirty (G-3).
//
// **An asset's name is one `asset(name)` can use** (spec §11 G-23): a name
// that is not is legalised (`GraphicAssetName`) and the copy filed under it,
// taking `-2`, `-3`, … while that name is held (scan or disk), so a RENAMED
// copy never replaces; the answer says the name used and the name asked for.
//
// **`landNew` is the `.fjgraphic` import's write** (spec §11 G-47 (e)): bytes
// already read, landed the same way but NEVER replacing — a file already at
// the name is a throw — and no rescan, which the import does once at its end.

import Foundation

extension GraphicStore {
    /// Copies `source` to `graphics/<subfolder>/<name>`, replacing a file of
    /// that name. Whether one was replaced. Main.
    func importFile(from source: URL, into subfolder: String, as name: String) throws
        -> (url: URL, replaced: Bool)
    {
        try ensureFolder()
        let files = FileManager.default
        let folder = folderURL.appendingPathComponent(subfolder, isDirectory: true)
        try files.createDirectory(at: folder, withIntermediateDirectories: true)
        let target = folder.appendingPathComponent(name)
        let replaced = try Self.land(at: target) { try files.copyItem(at: source, to: $0) }
        return (target, replaced)
    }

    /// `bytes` written to `graphics/<subfolder>/<name>` through a `.partial` beside it, never
    /// replacing: throws when a file is already there. Does not rescan. Main.
    func landNew(_ bytes: Data, into subfolder: String, as name: String) throws -> URL {
        try ensureFolder()
        let files = FileManager.default
        let folder = folderURL.appendingPathComponent(subfolder, isDirectory: true)
        try files.createDirectory(at: folder, withIntermediateDirectories: true)
        let target = folder.appendingPathComponent(name)
        guard !files.fileExists(atPath: target.path) else {
            throw ReelCoreError(message: "graphics/\(subfolder)/\(name) already exists")
        }
        let partial = folder.appendingPathComponent(name + ".partial")
        try? files.removeItem(at: partial)
        do {
            try bytes.write(to: partial)
            // `moveItem` refuses an existing target, so a file that appeared meanwhile stays.
            try files.moveItem(at: partial, to: target)
        } catch {
            try? files.removeItem(at: partial)
            throw error
        }
        return target
    }

    /// What `graphics/assets/` takes, in the refusals' words.
    static let assetKinds = "PNG, JPEG, GIF, WebP, SVG or SVGZ"

    /// A `.ttf` or `.otf` copied into `graphics/fonts/` under its own name,
    /// then `rescan()`. The families are the engine's reading of that file
    /// alone. Main.
    func importFont(from source: URL) throws -> (url: URL, replaced: Bool, families: [String]) {
        let path = source.path
        guard Self.fontExtensions.contains(source.pathExtension.lowercased()) else {
            throw ReelCoreError(message: "\(path) is not a .ttf or .otf file")
        }
        let bytes: Data
        do {
            bytes = try Data(contentsOf: source)
        } catch {
            throw ReelCoreError(
                message: "\(path) could not be read: \(error.localizedDescription)")
        }
        let probe = GraphicLibrary()
        do {
            try probe.addFont(bytes)
        } catch let error as ReelCoreError {
            throw ReelCoreError(message: "\(path): " + error.message)
        }
        let families = probe.families()
        let landed = try importNamed(source, Self.fontsFolderName, source.lastPathComponent)
        rescan()
        return (landed.url, landed.replaced, families)
    }

    /// A picture copied into `graphics/assets/<name>`, then `rescan()`.
    /// `name` is what `asset(name)` says; its extension must be one of the
    /// six. A name `asset(name)` cannot use is filed under a legal one
    /// (`renamedFrom` is the name asked for), never replacing a file. Main.
    func importAsset(from source: URL, as name: String) throws
        -> (url: URL, name: String, replaced: Bool, bytes: Int, renamedFrom: String?)
    {
        let path = source.path
        let kinds = Self.assetKinds
        guard !name.isEmpty, !name.contains("/") else {
            throw ReelCoreError(
                message: "name must be a file name with no / (got \"\(name)\") — it is what "
                    + "asset(name) says")
        }
        guard Self.assetExtensions.contains((name as NSString).pathExtension.lowercased())
        else {
            throw ReelCoreError(
                message: "\(name) is not a \(kinds) file (.png .jpg .jpeg .gif .webp .svg .svgz)")
        }
        let size = (try? FileManager.default.attributesOfItem(atPath: source.path)[.size]
            as? NSNumber)?.intValue ?? 0
        // An empty file crosses the FFI as NULL and the scan skips it.
        guard size > 0 else {
            throw ReelCoreError(
                message: "\(path) is empty (0 bytes) — an asset must hold a \(kinds) image")
        }
        let legal = GraphicAssetName.legalized(name)
        var used = legal
        if legal != name {
            var n = 2
            while holdsAsset(named: used) {
                used = GraphicAssetName.withSuffix(legal, n)
                n += 1
            }
        }
        let landed = try importNamed(source, Self.assetsFolderName, used)
        rescan()
        return (landed.url, used, landed.replaced, size, used == name ? nil : name)
    }

    /// True when the scan lists `name` or `graphics/assets/<name>` is on disk.
    func holdsAsset(named name: String) -> Bool {
        scan.assets.contains { $0.name == name }
            || FileManager.default.fileExists(
                atPath: folderURL.appendingPathComponent(Self.assetsFolderName, isDirectory: true)
                    .appendingPathComponent(name).path)
    }

    /// `importFile`, its failure said in a sentence naming the folder.
    private func importNamed(_ source: URL, _ subfolder: String, _ name: String) throws
        -> (url: URL, replaced: Bool)
    {
        do {
            return try importFile(from: source, into: subfolder, as: name)
        } catch {
            throw ReelCoreError(
                message: "graphics/\(subfolder)/\(name) could not be written: "
                    + error.localizedDescription)
        }
    }
}
// app/Sources/GraphicTemplates.swift — the graphic modules the app bundles
// as templates (road map 10's G5b): `graphic/tests/graphics/*.js`, copied
// into `Contents/Resources/GraphicTemplates/` by project.yml's "Copy Graphic
// Templates" script. Insert ▸ Graphic… lists them by category
// (`GraphicCatalog.swift`, spec §11 G-45); inserting one writes it into the
// package's `graphics/` under a free name and places a clip drawn by it.
//
// **`list(in:)` compiles nothing**: it reads the folder, and a template's
// `title` here is its FILE STEM's. The browser's titles come from each
// template's `meta.name` (`GraphicTemplateLibrary` compiles them once, when
// the browser first opens); `title(for:)` is the fallback for a module with
// no `meta.name`. A missing folder lists nothing.

import Foundation

/// One bundled template: its module name (the file stem), its menu title
/// and where the file is.
struct GraphicTemplate: Equatable {
    let name: String
    let title: String
    let url: URL
}

enum GraphicTemplates {
    static let folderName = "GraphicTemplates"

    /// The folder beside `Fonts/` — `GraphicStore.manualDirectory`'s rule,
    /// so a probe that copies `Fonts/` next to itself can copy this too.
    static func directory(besideFonts fonts: URL) -> URL {
        GraphicStore.manualDirectory(besideFonts: fonts)
            .appendingPathComponent(folderName, isDirectory: true)
    }

    /// The app bundle's own.
    static var bundledDirectory: URL {
        directory(besideFonts: ProjectDocument.bundledFontsDirectory)
    }

    /// Every `*.js` in `directory` whose stem is a module name, sorted by
    /// name; `[]` when the folder is absent.
    static func list(in directory: URL) -> [GraphicTemplate] {
        let entries = (try? FileManager.default.contentsOfDirectory(
            at: directory, includingPropertiesForKeys: nil,
            options: [.skipsHiddenFiles])) ?? []
        return entries.compactMap { url -> GraphicTemplate? in
            guard url.pathExtension == "js" else { return nil }
            let name = url.deletingPathExtension().lastPathComponent
            guard GraphicStore.isModuleName(name) else { return nil }
            return GraphicTemplate(name: name, title: title(for: name), url: url)
        }.sorted { $0.name < $1.name }
    }

    /// "lower-third" → "Lower Third": split on "-", each part capitalised.
    static func title(for name: String) -> String {
        name.split(separator: "-").map { part in
            part.prefix(1).uppercased() + part.dropFirst()
        }.joined(separator: " ")
    }

    /// A file stem made a module name: lowercased; every run of anything
    /// but `a-z0-9` one "-"; "-" trimmed from both ends; at most 63
    /// characters; "graphic" when nothing is left.
    static func moduleName(from stem: String) -> String {
        var scalars: [Unicode.Scalar] = []
        var pendingDash = false
        for scalar in stem.lowercased().unicodeScalars {
            if ("a"..."z").contains(scalar) || ("0"..."9").contains(scalar) {
                if pendingDash, !scalars.isEmpty { scalars.append("-") }
                pendingDash = false
                scalars.append(scalar)
            } else {
                pendingDash = true
            }
        }
        var name = String(String.UnicodeScalarView(scalars.prefix(63)))
        while name.hasSuffix("-") { name.removeLast() }
        return name.isEmpty ? "graphic" : name
    }
}
